"use client";
import {useEffect,useMemo,useState} from "react";import PageTitle from "@/composants/ui/PageTitle";import Section from "@/composants/ui/Section";import Input from "@/composants/ui/Input";import Alert from "@/composants/ui/Alert";import {serviceFinance} from "@/services/ServiceFinance.js";import {serviceAdministration} from "@/services/ServiceAdministration.js";
export default function Page(){const[data,setData]=useState({payouts:[]});const[relays,setRelays]=useState([]);const[selectedRelays,setSelectedRelays]=useState([]);const[selectedPayouts,setSelectedPayouts]=useState([]);const[period,setPeriod]=useState("Juillet 2026");const[feedback,setFeedback]=useState(null);async function refresh(){try{const[d,r]=await Promise.all([serviceFinance.getAll(),serviceAdministration.listUsers({role:'point_relais',statutCompte:'actif',limit:200})]);setData(d);setRelays(Array.isArray(r)?r:(r?.data||[]))}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de charger les paiements."})}}useEffect(()=>{refresh()},[]);const allRelays=relays.length>0&&selectedRelays.length===relays.length;const unpaid=useMemo(()=>data.payouts?.filter(i=>i.status!=="paye")||[],[data]);const allUnpaid=unpaid.length>0&&selectedPayouts.length===unpaid.length;function toggleRelay(id){setSelectedRelays(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id])}function togglePayout(id){setSelectedPayouts(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id])}async function generate(ids){try{setFeedback(null);const r=await serviceFinance.createPayoutsBulk(period,ids);setFeedback({type:"success",message:`${r.total} bon(s) de paiement généré(s)${r.skipped?.length?` · ${r.skipped.length} déjà existant(s)`:''}.`});setSelectedRelays([]);await refresh()}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de générer les bons de paiement."})}}async function paid(id){try{await serviceFinance.updatePayout(id,"paye");setSelectedPayouts(x=>x.filter(v=>v!==id));await refresh()}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de mettre à jour le bon."})}}async function paidBulk(ids){try{setFeedback(null);const r=await serviceFinance.updatePayoutsBulk(ids);setFeedback({type:"success",message:`${r.total} bon(s) marqué(s) payé(s).`});setSelectedPayouts([]);await refresh()}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de valider les paiements."})}}return <div className="space-y-8"><PageTitle title="Rémunération des points relais" description="Générez les bons de paiement en groupe ; le montant est calculé côté serveur à partir des colis réellement retirés."/>{feedback&&<Alert type={feedback.type} message={feedback.message}/>}<Section title="Génération groupée"><div className="max-w-md"><Input label="Période" name="period" value={period} onChange={e=>setPeriod(e.target.value)}/></div><div className="mt-5 flex flex-wrap gap-3"><button onClick={()=>generate([])} className="rounded-xl bg-indigo-600 px-5 py-3 text-sm font-bold text-white">Générer pour tous les points relais actifs</button><button disabled={!selectedRelays.length} onClick={()=>generate(selectedRelays)} className="rounded-xl border border-slate-300 px-5 py-3 text-sm font-bold text-slate-700 disabled:opacity-40">Générer la sélection ({selectedRelays.length})</button></div><div className="mt-5 overflow-hidden rounded-2xl border border-slate-200"><label className="flex items-center gap-3 border-b border-slate-200 bg-white/70 p-4 text-sm font-bold"><input type="checkbox" checked={allRelays} onChange={()=>setSelectedRelays(allRelays?[]:relays.map(r=>r.id))}/> Tout sélectionner</label>{relays.map(r=><label key={r.id} className="flex items-center gap-3 border-b border-slate-200 p-4 text-sm last:border-0"><input type="checkbox" checked={selectedRelays.includes(r.id)} onChange={()=>toggleRelay(r.id)}/><span className="font-semibold">{r.name}</span><span className="text-slate-600">{r.email}</span></label>)}</div></Section><Section title="Bons de paiement"><div className="mb-4 flex flex-wrap gap-3"><button disabled={!unpaid.length} onClick={()=>paidBulk(unpaid.map(i=>i.id))} className="rounded-xl bg-indigo-600 px-5 py-3 text-sm font-bold text-white disabled:opacity-40">Marquer tous les bons en attente comme payés</button><button disabled={!selectedPayouts.length} onClick={()=>paidBulk(selectedPayouts)} className="rounded-xl border border-slate-300 px-5 py-3 text-sm font-bold text-slate-700 disabled:opacity-40">Valider la sélection ({selectedPayouts.length})</button></div><label className="mb-3 flex items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-bold"><input type="checkbox" checked={allUnpaid} disabled={!unpaid.length} onChange={()=>setSelectedPayouts(allUnpaid?[]:unpaid.map(i=>i.id))}/> Sélectionner tous les bons en attente</label><div className="space-y-3">{data.payouts?.map(i=><div key={i.id} className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-slate-50 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3">{i.status!=="paye"&&<input className="mt-1" type="checkbox" checked={selectedPayouts.includes(i.id)} onChange={()=>togglePayout(i.id)}/>}<div><p className="font-bold">{i.relay}</p><p className="mt-1 text-sm text-slate-600">{i.period} · {i.parcels} colis × 1,50 € = {Number(i.amount).toFixed(2)} €</p></div></div><div className="flex gap-3"><span className={`rounded-full px-3 py-1 text-xs font-bold ${i.status==="paye"?"bg-indigo-500/10 text-indigo-700":"bg-amber-500/10 text-amber-800"}`}>{i.status}</span>{i.status!=="paye"&&<button onClick={()=>paid(i.id)} className="text-xs font-bold text-blue-700">Marquer payé</button>}</div></div>)}</div></Section></div>}
